from collections import deque

def minimize_string_length(s):
    stack = deque()
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

s = input()
print(minimize_string_length(s))

from collections import defaultdict

def minimize_string_length(s):
    char_count = defaultdict(int)
    for char in s:
        char_count[char] += 1

    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

