def find_max_pairs(words):
    pairs = 0
    used = [False] * len(words)
    for i in range(len(words)):
        if used[i]:
            continue
        for j in range(i + 1, len(words)):
            if used[j]:
                continue
            if words[i] == words[j][::-1]:
                pairs += 1
                used[i] = True
                used[j] = True
                break
    return pairs

