def find_longest_alternating_subarray(nums):
    max_length = -1
    for i in range(len(nums)):
        for j in range(i + 2, len(nums) + 1):
            subarray = nums[i:j]
            if is_alternating(subarray):
                max_length = max(max_length, len(subarray))
    return max_length

def is_alternating(subarray):
    if len(subarray) < 2:
        return False
    diff = subarray[1] - subarray[0]
    if diff != 1:
        return False
    for i in range(2, len(subarray)):
        new_diff = subarray[i] - subarray[i - 1]
        if new_diff != -diff:
            return False
        diff = new_diff
    return True

