import sys

moves = input().strip()

def calculate_distance(moves):
    max_distance = 0
    for i in range(2**moves.count('_')):
        binary_string = bin(i)[2:].zfill(moves.count('_'))
        modified_moves = list(moves)
        underscore_index = 0
        for j in range(len(modified_moves)):
            if modified_moves[j] == '_':
                modified_moves[j] = 'R' if binary_string[underscore_index] == '1' else 'L'
                underscore_index += 1
        position = 0
        for move in modified_moves:
            if move == 'R':
                position += 1
            else:
                position -= 1
        max_distance = max(max_distance, abs(position))
    return max_distance

print(calculate_distance(moves))

