def find_longest_sequential_prefix(nums):
    max_length = 1
    max_prefix_sum = nums[0]
    current_length = 1
    current_prefix_sum = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            current_length += 1
            current_prefix_sum += nums[i]
        else:
            if current_length > max_length:
                max_length = current_length
                max_prefix_sum = current_prefix_sum
            current_length = 1
            current_prefix_sum = nums[i]

    if current_length > max_length:
        max_length = current_length
        max_prefix_sum = current_prefix_sum

    return max_prefix_sum

def find_smallest_missing_integer(nums, target):
    num_set = set(nums)
    while target not in num_set:
        if target not in num_set:
            return target
        target += 1

