def count_incremovable_subarrays(nums):
    count = 0
    for length in range(1, len(nums) + 1):
        for i in range(len(nums) - length + 1):
            subarray = nums[i:i+length]
            new_array = nums[:i] + nums[i+length:]
            if is_increasing(new_array):
                count += 1
    return count

