import sys

def can_split(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    nums1_count = 0
    nums2_count = 0
    for key, value in count.items():
        if value == 1:
            nums1_count += 1
        elif value == 2:
            nums1_count += 1
            nums2_count += 1
        else:
            if nums1_count < len(nums) // 2:
                nums1_count += 1
                value -= 1
            if nums2_count < len(nums) // 2 and value > 1:
                nums2_count += 1
                value -= 1
            if nums1_count < len(nums) // 2 and value > 0:
                nums1_count += 1
            if nums2_count < len(nums) // 2 and value > 0:
                nums2_count += 1

    return nums1_count == len(nums) // 2 and nums2_count == len(nums) // 2

nums = list(map(int, input().strip('[]').split(', ')))
print(can_split(nums))

