import sys

def fill_gaps(sequence):
    i = 0
    while i < len(sequence) - 1:
        if abs(sequence[i] - sequence[i + 1]) != 1:
            if sequence[i] < sequence[i + 1]:
                sequence = sequence[:i + 1] + list(range(sequence[i] + 1, sequence[i + 1])) + sequence[i + 1:]
            else:
                sequence = sequence[:i + 1] + list(range(sequence[i] - 1, sequence[i + 1] - 1, -1)) + sequence[i + 1:]
            i = 0
        else:
            i += 1
    return sequence

