import sys

def is_tak_code(grid, i, j):
    # Check top-left 3x3 region
    for x in range(3):
        for y in range(3):
            if grid[i+x][j+y] != '#':
                return False

    # Check bottom-right 3x3 region
    for x in range(6, 9):
        for y in range(6, 9):
            if grid[i+x][j+y] != '#':
                return False

    # Check adjacent cells
    for x in range(9):
        for y in range(9):
            if (x < 3 and y < 3) or (x >= 6 and y >= 6):
                continue
            if (x == 3 and y < 3) or (x == 5 and y < 3) or (y == 3 and x < 3) or (y == 5 and x < 3) or (x == 3 and y >= 6) or (x == 5 and y >= 6) or (y == 3 and x >= 6) or (y == 5 and x >= 6):
                if grid[i+x][j+y] != '.':
                    return False

    return True

