    n, m = map(int, input().split())
    grid = [list(input()) for _ in range(n)]

    result = []
    for i in range(n-8):
        for j in range(m-8):
            if is_tak_code(grid, i, j):
                result.append((i+1, j+1))

    for i, j in sorted(result):
        print(i, j)

