import sys

def calculate_min_cost(N, S, M, L):
    min_cost = float('inf')
    for i in range(N // 6 + 1):
        for j in range(N // 8 + 1):
            remaining_eggs = N - i * 6 - j * 8
            if remaining_eggs < 0:
                continue
            if remaining_eggs % 12 == 0:
                cost = i * S + j * M + (remaining_eggs // 12) * L
                min_cost = min(min_cost, cost)
    for i in range(N // 6 + 1):
        for j in range(N // 12 + 1):
            remaining_eggs = N - i * 6 - j * 12
            if remaining_eggs < 0:
                continue
            if remaining_eggs % 8 == 0:
                cost = i * S + j * L + (remaining_eggs // 8) * M
                min_cost = min(min_cost, cost)
    for i in range(N // 8 + 1):
        for j in range(N // 12 + 1):
            remaining_eggs = N - i * 8 - j * 12
            if remaining_eggs < 0:
                continue
            if remaining_eggs % 6 == 0:
                cost = i * M + j * L + (remaining_eggs // 6) * S
                min_cost = min(min_cost, cost)
    for i in range(N // 6 + 1):
        remaining_eggs = N - i * 6
        if remaining_eggs < 0:
            continue
        if remaining_eggs % 8 == 0:
            cost = i * S + (remaining_eggs // 8) * M
            min_cost = min(min_cost, cost)
        elif remaining_eggs % 12 == 0:
            cost = i * S + (remaining_eggs // 12) * L
            min_cost = min(min_cost, cost)
    for i in range(N // 8 + 1):
        remaining_eggs = N - i * 8
        if remaining_eggs < 0:
            continue
        if remaining_eggs % 6 == 0:
            cost = i * M + (remaining_eggs // 6) * S
            min_cost = min(min_cost, cost)
        elif remaining_eggs % 12 == 0:
            cost = i * M + (remaining_eggs // 12) * L
            min_cost = min(min_cost, cost)
    for i in range(N // 12 + 1):
        remaining_eggs = N - i * 12
        if remaining_eggs < 0:
            continue
        if remaining_eggs % 6 == 0:
            cost = i * L + (remaining_eggs // 6) * S
            min_cost = min(min_cost, cost)
        elif remaining_eggs % 8 == 0:
            cost = i * L + (remaining_eggs // 8) * M
            min_cost = min(min_cost, cost)
    if N % 6 == 0:
        cost = (N // 6) * S
        min_cost = min(min_cost, cost)
    if N % 8 == 0:
        cost = (N // 8) * M
        min_cost = min(min_cost, cost)
    if N % 12 == 0:
        cost = (N // 12) * L
        min_cost = min(min_cost, cost)
    return min_cost

