print(calculate_min_cost(N, S, M, L))

def check_extended_abc(s):
    seen = set()
    for char in s:
        if char not in seen:
            seen.add(char)
        else:
            if len(seen) == 1 and char != list(seen)[0]:
                return False
            if len(seen) == 2 and char != 'C':
                return False
    return len(seen) <= 3 and ('A' in seen or not seen) and ('B' in seen or not seen) and ('C' in seen or not seen)

s = input()
if check_extended_abc(s):
    print("Yes")
else:
