import heapq

def main():
    nums = list(map(int, input().split()))
    k = int(input())

    pq = []
    for num in nums:
        bits = []
        temp = num
        for i in range(31, -1, -1):
            if temp & (1 << i):
                bits.append(i)
        heapq.heappush(pq, (-bits[0], bits, num))

    for _ in range(k):
        _, bits, num = heapq.heappop(pq)
        new_num = num * 2
        new_bits = []
        temp = new_num
        for i in range(31, -1, -1):
            if temp & (1 << i):
                new_bits.append(i)
        heapq.heappush(pq, (-new_bits[0], new_bits, new_num))

    res = 0
    while pq:
        _, _, num = heapq.heappop(pq)
        res |= num

    print(res)

if __name__ == "__main__":
    main()

import sys
import heapq

def main():
    nums = list(map(int, input().split()))
    k = int(input())

    pq = []
    for num in nums:
        bits = for i in range(31, -1, -1):
            if (num >> i) & 1:
                bits.append(i)
        heapq.heappush(pq, (-len(bits), bits))

    for _ in range(k):
        _, bits = heapq.heappop(pq)
        if not bits:
            continue
        bit = bits.pop()
        heapq.heappush(pq, (-len(bits), bits))

    res = 0
    while pq:
        _, bits = heapq.heappop(pq)
        for bit in bits:
            res |= 1 << bit
    print(res)

if __name__ == "__main__":
    main()

