def smallest_string(s):
    n = len(s)
    result = list(s)
    for i in range(n):
        for j in range(i, n):
            temp = list(s)
            for k in range(i, j + 1):
                if temp[k] == 'a':
                    temp[k] = 'z'
                else:
                    temp[k] = chr(ord(temp[k]) - 1)
            if temp < result:
                result = temp
    return ''.join(result)

