def find_longest_equal_subarray(nums, k):
    max_length = 0
    for num in set(nums):
        left = 0
        count = 0
        for right in range(len(nums)):
            if nums[right]!= num:
                count += 1
            while count > k:
                if nums[left]!= num:
                    count -= 1
                left += 1
            max_length = max(max_length, right - left + 1)
    return max_length

