import sys

def min_operations(num1, num2):
    if num2 == 0:
        if num1 == 0:
            return 0
        else:
            return -1

    operations = 0
    while num1 != 0:
        if num1 * num2 < 0:
            return -1
        if num1 % num2 == 0:
            return operations + num1 // num2
        for i in range(60, -1, -1):
            if num1 - (2**i + num2) >= 0:
                num1 -= (2**i + num2)
                operations += 1
                break
    return operations

