def calculate_length(x, y, z):
    length = 0
    while True:
        if x > 0 and y > 0:
            if x > y:
                if z > 0:
                    length += 2
                    x -= 1
                    y -= 1
                    z -= 1
                else:
                    length += 2
                    x -= 1
                    y -= 1
            else:
                if z > 0:
                    length += 2
                    x -= 1
                    y -= 1
                    z -= 1
                else:
                    length += 2
                    x -= 1
                    y -= 1
        elif x > 0 and z > 0:
            length += 2
            x -= 1
            z -= 1
        elif y > 0 and z > 0:
            length += 2
            y -= 1
            z -= 1
        elif x > 0 and x < 3:
            length += 2 * x
            x = 0
        elif y > 0 and y < 3:
            length += 2 * y
            y = 0
        else:
            break
    return length

print(calculate_length(x, y, z))

