def max_jumps(nums, target):
    n = len(nums)
    jumps = [1] * n
    for i in range(1, n):
        for j in range(i):
            if -target <= nums[i] - nums[j] <= target:
                jumps[i] = max(jumps[i], jumps[j] + 1)
    return jumps[-1] if jumps[-1] > 1 else -1

