def longest_non_decreasing_subarray(nums1, nums2):
    n = len(nums1)
    max_length = 1
    for i in range(n):
        for j in range(i, n):
            subarray = []
            for k in range(i, j + 1):
                subarray.append(min(nums1[k], nums2[k]))
            for k in range(i, j + 1):
                if nums1[k] > subarray[-1]:
                    subarray.append(nums1[k])
                elif nums2[k] > subarray[-1]:
                    subarray.append(nums2[k])
            if all(subarray[k] <= subarray[k + 1] for k in range(len(subarray) - 1)):
                max_length = max(max_length, len(subarray))
    return max_length

