def largest_element(nums):
    while len(nums) > 1:
        max_index = 0
        max_sum = 0
        for i in range(len(nums) - 1):
            if nums[i] <= nums[i + 1] and nums[i] + nums[i + 1] > max_sum:
                max_index = i
                max_sum = nums[i] + nums[i + 1]
        if max_sum == 0:
            break
        nums[max_index] = max_sum
        nums.pop(max_index + 1)
    return max(nums)

