def shortest_string(a, b, c):
    min_length = float('inf')
    result = ""
    for p in permutations([a, b, c]):
        for i in range(len(p[0]) + 1):
            for j in range(len(p[1]) + 1):
                s = p[0][:i] + p[1] + p[0][i:]
                s = s[:j] + p[2] + s[j:]
                if a in s and b in s and c in s and len(s) < min_length:
                    min_length = len(s)
                    result = s
                elif a in s and b in s and c in s and len(s) == min_length and s < result:
                    result = s
    return result

