def main():
    n = int(input())
    x = int(input())
    MOD = 10**9 + 7

    memo = {}

    def dp(n):
        if n in memo:
            return memo[n]
        if n == 0:
            return 1
        if n < 0:
            return 0
        res = 0
        i = 1
        while i**x <= n:
            res = (res + dp(n - i**x)) % MOD
            i += 1
        memo[n] = res
        return res

    print(dp(n))

