def is_beautiful(s):
    if s[0] == '0' and len(s) > 1:
        return False
    num = int(s, 2)
    n = 0
    while 5 ** n <= num:
        if 5 ** n == num:
            return True
        n += 1
    return False

def partition_string(s):
    memo = {}

    def dfs(s):
        if s in memo:
            return memo[s]
        if not s:
            return 0
        res = float('inf')
        for i in range(1, len(s) + 1):
            if is_beautiful(s[:i]):
                if not s[i:]:
                    res = min(res, 1)
                else:
                    res = min(res, 1 + dfs(s[i:]))
        memo[s] = res
        return res

    res = dfs(s)
    return res if res != float('inf') else -1

