import sys

def find_dominant_element(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
    for num, freq in count.items():
        if freq * 2 > len(nums):
            return num
    return None

def is_valid_split(nums, i):
    left = nums[:i+1]
    right = nums[i+1:]
    dominant = find_dominant_element(nums)
    return find_dominant_element(left) == dominant and find_dominant_element(right) == dominant

def find_minimum_index(nums):
    dominant = find_dominant_element(nums)
    for i in range(len(nums) - 1):
        left = nums[:i+1]
        right = nums[i+1:]
        count_left = left.count(dominant)
        count_right = right.count(dominant)
        if count_left * 2 > len(left) and count_right * 2 > len(right):
            return i
    return -1

