def calculate_score(nums, x):
    n = len(nums)
    even = [0] * n
    odd = [0] * n

    if nums[0] % 2 == 0:
        even[0] = nums[0]
    else:
        odd[0] = nums[0]

    for i in range(1, n):
        if nums[i] % 2 == 0:
            even[i] = max(even[i-1] + nums[i], odd[i-1] + nums[i] - x)
            odd[i] = odd[i-1]
        else:
            odd[i] = max(odd[i-1] + nums[i], even[i-1] + nums[i] - x)
            even[i] = even[i-1]

    return max(even[-1], odd[-1])

