def can_split(nums, m, n):
    if len(nums) == n:
        return True

    for i in range(1, len(nums)):
        left = nums[:i]
        right = nums[i:]

        if (len(left) == 1 or sum(left) >= m) and (len(right) == 1 or sum(right) >= m):
            if can_split(left, m, min(n, len(left))) and can_split(right, m, n - min(n, len(left))):
                return True

    return False

