def can_split(nums, m, n):
    if len(nums) == n:
        return all(x == 1 for x in nums)

    for i in range(1, len(nums)):
        left_sum = sum(nums[:i])
        right_sum = sum(nums[i:])

        if (left_sum >= m or len(nums[:i]) == 1) and (right_sum >= m or len(nums[i:]) == 1):
            if can_split(nums[:i], m, 1) and can_split(nums[i:], m, n - 1):
                return True

    return False

