            for i in range(n):
                if nums[i] == target:
                    new_nums[i] = target
                elif nums[(i - 1 + n) % n] == target:
                    new_nums[i] = target
                elif nums[(i + 1) % n] == target:
                    new_nums[i] = target
            if new_nums == nums:
                break
            nums = new_nums
            seconds += 1
        min_seconds = min(min_seconds, seconds)

