def min_seconds_to_equalize(nums):
    n = len(nums)
    max_count = 0
    max_num = None
    count = {}

    for num in nums:
        if num not in count:
            count[num] = 1
        else:
            count[num] += 1

        if count[num] > max_count:
            max_count = count[num]
            max_num = num

    if max_count == n:
        return 0

    seconds = 0
    while True:
        new_nums = []
        for i in range(n):
            new_nums.append(max([nums[(i-1)%n], nums[i], nums[(i+1)%n]]))
        nums = new_nums
        seconds += 1

        if len(set(nums)) == 1:
            break

    return seconds

