def min_operations(num):
    n = len(num)
    min_ops = float('inf')

    for mask in range(1 << n):
        temp = []
        for i in range(n):
            if (mask & (1 << i)):
                temp.append(num[i])
        temp_num = ''.join(temp)
        if not temp_num:
            temp_num = '0'
        if int(temp_num) % 25 == 0:
            min_ops = min(min_ops, n - len(temp))

    return min_ops

