from itertools import combinations

def is_special(num):
    """Check if a number is special (divisible by 25)."""
    return int(num) % 25 == 0

def min_operations(num):
    """Find the minimum number of operations to make a special number."""
    min_ops = float('inf')
    for r in range(len(num) + 1):
        for combo in combinations(num, r):
            remaining_num = ''.join([c for c in num if c not in combo])
            if remaining_num and is_special(remaining_num):
                min_ops = min(min_ops, len(combo))
            elif not remaining_num and is_special('0'):
                min_ops = min(min_ops, len(combo))
    return min_ops

num = input()
print(min_operations(num))

