    dp = [[-1] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = 0

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - nums[i - 1]] + 1)

    max_length = max(dp[i][target] for i in range(n + 1))
    print(max_length if max_length != -1 else -1)

