def read_input():
    nums = list(map(int, input().split()))
    target = int(input())
    return nums, target

def length_of_longest_subsequence(nums, target):
    memo = {}

    def dfs(i, target):
        if (i, target) in memo:
            return memo[(i, target)]
        if target == 0:
            return 0
        if i == len(nums) or target < 0:
            return -float('inf')
        take = 1 + dfs(i + 1, target - nums[i])
        skip = dfs(i + 1, target)
        memo[(i, target)] = max(take, skip)
        return memo[(i, target)]

    max_length = dfs(0, target)
    return max_length if max_length > 0 else -1

