def length_of_longest_subsequence(nums, target):
    n = len(nums)
    dp = [[-1] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(target + 1):
            if j < nums[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - nums[i - 1]] + 1 if dp[i - 1][j - nums[i - 1]]!= -1 else -1)

    return dp[n][target]

