import sys

def is_mountain(heights):
    n = len(heights)
    if n < 3:
        return False
    i = 0
    while i < n - 1 and heights[i] <= heights[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i < n - 1 and heights[i] >= heights[i + 1]:
        i += 1
    return i == n - 1

def max_sum_of_heights(maxHeights):
    n = len(maxHeights)
    max_sum = 0
    for i in range(n):
        for j in range(1, maxHeights[i] + 1):
            heights = [min(maxHeights[k], j) if k <= i else min(maxHeights[k], j) for k in range(n)]
            for k in range(i - 1, -1, -1):
                heights[k] = min(heights[k], heights[k + 1])
            for k in range(i + 1, n):
                heights[k] = min(heights[k], heights[k - 1])
            if is_mountain(heights):
                max_sum = max(max_sum, sum(heights))
    return max_sum

