import sys

MOD = 10**9 + 7

def calculate_combinations(n, k):
    """Calculate the number of combinations of n items taken k at a time."""
    if k > n:
        return 0
    result = 1
    for i in range(1, k + 1):
        result = (result * (n - i + 1)) // i
    return result

def calculate_permutations(n, k):
    """Calculate the number of permutations of n items taken k at a time."""
    if k > n:
        return 0
    result = 1
    for i in range(n, n - k, -1):
        result = (result * i) % MOD
    return result

def main():
    n = int(input())
    total_strings = 26 ** n
    bad_strings = 0

    # Calculate the number of bad strings
    for i in range(n + 1):
        for j in range(n + 1 - i):
            for k in range(n + 1 - i - j):
                remaining = n - i - j - k
                if remaining < 0:
                    continue
                if i < 2 or j < 2 or k < 1:
                    bad_strings += calculate_combinations(n, i) * calculate_combinations(n - i, j) * calculate_combinations(n - i - j, k)
                    bad_strings %= MOD

    good_strings = (total_strings - bad_strings) % MOD
    print(good_strings)

