import sys

def read_input():
    return sys.stdin.readline().strip()

def read_ints():
    return list(map(int, read_input().split()))

def read_int():
    return int(read_input())

def solve(nums, limit):
    n = len(nums)
    parent = list(range(n))

    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x!= root_y:
            parent[root_x] = root_y

    for i in range(n):
        for j in range(i + 1, n):
            if abs(nums[i] - nums[j]) <= limit:
                union(i, j)

    groups = {}
    for i in range(n):
        root = find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(nums[i])

    for root in groups:
        groups[root].sort()

    result = [0] * n
    for i in range(n):
        root = find(i)
        result[i] = groups[root].pop(0)

    return result

nums = read_ints()
limit = read_int()
print(*solve(nums, limit))

