def main():
    nums1 = list(map(int, input().split()))
    nums2 = list(map(int, input().split()))

    n = len(nums1)
    count1 = {}
    count2 = {}

    for num in nums1:
        if num in count1:
            count1[num] += 1
        else:
            count1[num] = 1

    for num in nums2:
        if num in count2:
            count2[num] += 1
        else:
            count2[num] = 1

    common = set(count1.keys()) & set(count2.keys())
    unique1 = set(count1.keys()) - common
    unique2 = set(count2.keys()) - common

    remove = n // 2
    ans = 0

    for num in common:
        ans += min(count1[num], count2[num])
        remove -= min(count1[num], count2[num])

    for num in unique1:
        ans += min(count1[num], remove)
        remove -= min(count1[num], remove)

    for num in unique2:
        ans += min(count2[num], remove)
        remove -= min(count2[num], remove)

    print(n - ans)

