def min_coins_to_add(coins, target):
    dp = [float('inf')] * (target + 1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, target + 1):
            dp[i] = min(dp[i], dp[i - coin] + 1)
    result = 0
    for i in range(1, target + 1):
        if dp[i] == float('inf'):
            result += 1
            dp[i] = 1
            for j in range(i + i, target + 1, i):
                dp[j] = min(dp[j], dp[j - i] + 1)
    return result

