import heapq

def main():
    source = input()
    target = input()
    original = input().strip("[]").split(", ")
    changed = input().strip("[]").split(", ")
    cost = list(map(int, input().strip("[]").split(", ")))

    graph = {}
    for i in range(len(original)):
        if original[i] not in graph:
            graph[original[i]] = []
        graph[original[i]].append((changed[i], cost[i]))

    def dijkstra(start, end):
        queue = [(0, start)]
        visited = set()
        while queue:
            current_cost, current_node = heapq.heappop(queue)
            if current_node == end:
                return current_cost
            if current_node in visited:
                continue
            visited.add(current_node)
            if current_node in graph:
                for neighbor, neighbor_cost in graph[current_node]:
                    heapq.heappush(queue, (current_cost + neighbor_cost, neighbor))
        return -1

    total_cost = 0
    for i in range(len(source)):
        if source[i]!= target[i]:
            cost = dijkstra(source[i], target[i])
            if cost == -1:
                print(-1)
                return
            total_cost += cost
    print(total_cost)

if __name__ == "__main__":
    main()

