import sys

def calculate_price(num, x):
    price = 0
    binary = bin(num)[2:][::-1]
    for i in range(len(binary)):
        if i % x == 0 and binary[i] == '1':
            price += 1
    return price

def find_greatest_integer(k, x):
    left, right = 1, 10**18
    while left <= right:
        mid = (left + right) // 2
        total_price = sum(calculate_price(i, x) for i in range(1, mid + 1))
        if total_price <= k:
            left = mid + 1
        else:
            right = mid - 1
    return right

k = int(input())
x = int(input())
print(find_greatest_integer(k, x))

