import sys

def find_beautiful_indices(s, a, b, k):
    beautiful_indices = []
    a_indices = [i for i in range(len(s) - len(a) + 1) if s[i:i + len(a)] == a]
    b_indices = [i for i in range(len(s) - len(b) + 1) if s[i:i + len(b)] == b]

    for i in a_indices:
        for j in b_indices:
            if abs(i - j) <= k:
                beautiful_indices.append(i)
                break

    return sorted(set(beautiful_indices))

