import sys

def min_operations(nums, k):
    xor = 0
    for num in nums:
        xor ^= num

    if xor == k:
        return 0

    max_bits = max(max(num.bit_length() for num in nums), k.bit_length())
    min_ops = float('inf')

    for num in nums:
        num_bits = num.bit_length()
        for i in range(max_bits + 1):
            flipped_num = num ^ (1 << i)
            new_xor = xor ^ num ^ flipped_num
            if new_xor == k:
                min_ops = min(min_ops, 1)
            elif new_xor ^ k < min_ops:
                min_ops = new_xor ^ k

    return min_ops

