print(min_operations(nums, k))

import sys

def min_operations(nums, k):
    xor = 0
    for num in nums:
        xor ^= num

    if xor == k:
        return 0

    max_bits = max(max(nums), k).bit_length()
    min_ops = float('inf')

    for num in nums:
        for i in range(max_bits + 1):
            flipped_num = num ^ (1 << i)
            new_xor = xor ^ num ^ flipped_num
            if new_xor == k:
                min_ops = min(min_ops, 1)

    if min_ops == float('inf'):
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                num1, num2 = nums[i], nums[j]
                for bit1 in range(max_bits + 1):
                    for bit2 in range(max_bits + 1):
                        flipped_num1 = num1 ^ (1 << bit1)
                        flipped_num2 = num2 ^ (1 << bit2)
                        new_xor = xor ^ num1 ^ num2 ^ flipped_num1 ^ flipped_num2
                        if new_xor == k:
                            min_ops = min(min_ops, 2)

    return min_ops if min_ops != float('inf') else -1

nums = list(map(int, input().split()))
k = int(input())
print(min_operations(nums, k))

