import sys

def count_set_bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def can_sort_array(nums):
    groups = {}
    for num in nums:
        set_bits = count_set_bits(num)
        if set_bits not in groups:
            groups[set_bits] = []
        groups[set_bits].append(num)

    for group in groups.values():
        group.sort()

    sorted_nums = []
    for group in sorted(groups.keys()):
        sorted_nums.extend(groups[group])

    return sorted_nums == sorted(nums)

nums = list(map(int, input().strip()[1:-1].split(', ')))
print(can_sort_array(nums))

