def main():
    nums = list(map(int, input().split()))
    changeIndices = list(map(int, input().split()))

    n = len(nums)
    m = len(changeIndices)

    marked = [False] * n
    count = 0

    for s in range(m):
        if nums[changeIndices[s] - 1] == 0 and not marked[changeIndices[s] - 1]:
            marked[changeIndices[s] - 1] = True
            count += 1

        if count == n:
            print(s + 1)
            return

        if count < n:
            min_val = float('inf')
            min_index = -1
            for i in range(n):
                if not marked[i] and nums[i] < min_val:
                    min_val = nums[i]
                    min_index = i

            nums[min_index] -= 1

    if count < n:
        print(-1)
    else:
        print(m)

if __name__ == "__main__":
    main()

