import sys

def find_max_subset(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    max_length = 0
    for num in count:
        current_length = 0
        current_num = num
        while current_num in count and count[current_num] > 0:
            count[current_num] -= 1
            current_length += 1
            current_num *= num
        current_num //= num
        while current_num != num and current_num in count and count[current_num] > 0:
            count[current_num] -= 1
            current_length += 1
            current_num //= num
        max_length = max(max_length, current_length)

    return max_length

nums = list(map(int, input().split(',')))
print(find_max_subset(nums))

