def main():
    nums = list(map(int, input().split()))
    max_count = 0

    for num in set(nums):
        count = nums.count(num)
        if count > 0:
            max_count = max(max_count, count)

        square = num ** 2
        if square in nums:
            count = min(count, nums.count(square))
            if square ** 2 in nums:
                count = min(count, nums.count(square ** 2))
                if square ** 4 in nums:
                    count = min(count, nums.count(square ** 4))
                    if square ** 8 in nums:
                        count = min(count, nums.count(square ** 8))
                        if square ** 16 in nums:
                            count = min(count, nums.count(square ** 16))
                            if square ** 32 in nums:
                                count = min(count, nums.count(square ** 32))
            max_count = max(max_count, count * 2 + 1 if count > 0 else 0)

    print(max_count)

