from collections import Counter

def count_palindromes(words):
    char_count = Counter()
    for word in words:
        for char in word:
            char_count[char] += 1

    odd_count = sum(count % 2 for count in char_count.values())
    return len(words) - (odd_count - 1 if odd_count > 0 else 0)

words = input().strip("[]").split(',"')
words = [word.strip('"') for word in words]
print(count_palindromes(words))

