import sys

def find_common_prefix_length(x, y):
    """Find the length of the common prefix between two integers."""
    x_str = str(x)
    y_str = str(y)
    length = 0
    for i in range(min(len(x_str), len(y_str))):
        if x_str[i] == y_str[i]:
            length += 1
        else:
            break
    return length

def main():
    """Read input, compute the answer, and print the result."""
    arr1 = list(map(int, input().split()))
    arr2 = list(map(int, input().split()))
    max_length = 0
    for x in arr1:
        for y in arr2:
            length = find_common_prefix_length(x, y)
            max_length = max(max_length, length)
    print(max_length)

if __name__ == "__main__":
    main()

