    return length

def find_longest_common_prefix_length(arr1, arr2):
    """Find the length of the longest common prefix among all pairs of integers."""
    max_length = 0
    for x in arr1:
        for y in arr2:
            length = find_common_prefix_length(x, y)
            max_length = max(max_length, length)
    return max_length

