import sys

def count_chars(s):
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

def main():
    s = input().strip()
    t = input().strip()

    s_count = count_chars(s.replace('@', ''))
    t_count = count_chars(t.replace('@', ''))

    if s_count!= t_count:
        print('No')
        return

    s_at_count = s.count('@')
    t_at_count = t.count('@')

    if s_at_count + t_at_count > 7 * 2:
        print('No')
        return

    s_set = set(s.replace('@', ''))
    t_set = set(t.replace('@', ''))

    if len(s_set.union(t_set)) > 7:
        print('No')
        return

    print('Yes')

if __name__ == '__main__':
    main()

import sys

def main():
    N, M, H, K = map(int, input().split())
    S = input()
    items = set()
    for _ in range(M):
        x, y = map(int, input().split())
        items.add((x, y))

    x, y = 0, 0
    for s in S:
        if s == 'R':
            x += 1
        elif s == 'L':
            x -= 1
        elif s == 'U':
            y += 1
        elif s == 'D':
            y -= 1
        H -= 1
        if (x, y) in items and H < K:
            H = K
            items.remove((x, y))
        if H < 0:
            print("No")
            return
    print("Yes")

if __name__ == "__main__":
    main()

