X, Y, Z = map(int, input().split())
S = input()

def calculate_cost(S, X, Y, Z):
    cost = 0
    caps_lock_on = False
    for char in S:
        if caps_lock_on:
            if char == 'A':
                cost += X
            else:
                cost += Y
        else:
            if char == 'A':
                cost += Y
            else:
                cost += X
        if (caps_lock_on and char == 'a') or (not caps_lock_on and char == 'A'):
            if cost > 0 and S[S.index(char) - 1]!= char:
                cost += Z
                caps_lock_on = not caps_lock_on
    return cost

def calculate_cost2(S, X, Y, Z):
    cost = 0
    caps_lock_on = False
    for char in S:
        if caps_lock_on:
            if char == 'A':
