import sys

def find_cookie():
    H, W = map(int, input().split())
    grid = [list(input()) for _ in range(H)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                # Check if the current cell is part of a rectangle
                for a in range(i):
                    for b in range(i + 1, H):
                        for c in range(j):
                            for d in range(j + 1, W):
                                if is_rectangle(grid, a, b, c, d, i, j):
                                    return i + 1, j + 1

def is_rectangle(grid, a, b, c, d, x, y):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (a <= i <= b and c <= j <= d) and grid[i][j] != '#':
                if (i, j) != (x, y):
                    return False
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if not (a <= i <= b and c <= j <= d) and grid[i][j] == '#':
                return False
    return True

