import sys

def read_sheet():
    h, w = map(int, input().split())
    sheet = [input() for _ in range(h)]
    return h, w, sheet

def count_black_squares(sheet):
    return sum(row.count('#') for row in sheet)

def check_position(a, b, x, ax, ay, bx, by):
    h_x, w_x, x_sheet = x
    h_a, w_a, a_sheet = a
    h_b, w_b, b_sheet = b

    black_squares = set()

    for i in range(h_a):
        for j in range(w_a):
            if a_sheet[i][j] == '#':
                black_squares.add((i + ax, j + ay))

    for i in range(h_b):
        for j in range(w_b):
            if b_sheet[i][j] == '#':
                black_squares.add((i + bx, j + by))

    for i in range(h_x):
        for j in range(w_x):
            if x_sheet[i][j] == '#':
                if (i + ax, j + ay) not in black_squares and (i + bx, j + by) not in black_squares:
                    return False

    return True

def check_sheets(a, b, x):
    h_a, w_a, a_sheet = a
    h_b, w_b, b_sheet = b
    h_x, w_x, x_sheet = x

    for ax in range(-h_x + 1, h_a + 1):
        for ay in range(-w_x + 1, w_a + 1):
            for bx in range(-h_x + 1, h_b + 1):
                for by in range(-w_x + 1, w_b + 1):
                    if check_position(a, b, x, ax, ay, bx, by):
                        return True

    return False

def main():
    a = read_sheet()
    b = read_sheet()
    x = read_sheet()

    if count_black_squares(a) + count_black_squares(b) != count_black_squares(x):
        print("No")
    elif check_sheets(a, b, x):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

