def read_input():
    H, W = map(int, input().split())
    S = [input() for _ in range(H)]
    return H, W, S

def is_valid_move(i, j, H, W):
    return 0 <= i < H and 0 <= j < W

def dfs(i, j, k, H, W, S, visited):
    if k == 10:
        return True
    if not is_valid_move(i, j, H, W) or visited[i][j] or S[i][j] != 'snuke'[k % 5]:
        return False
    visited[i][j] = True
    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        if dfs(i + di, j + dj, k + 1, H, W, S, visited):
            return True
    visited[i][j] = False
    return False

