import sys

def read_input():
    return sys.stdin.readline().strip()

def read_ints():
    return list(map(int, read_input().split()))

def main():
    N, M = read_ints()
    graph = [[] for _ in range(N + 1)]
    for _ in range(M):
        A, B = read_ints()
        graph[A].append(B)

    def dfs(node, visited, stack):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
        stack.append(node)

    visited = [False] * (N + 1)
    stack = []
    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i, visited, stack)

    scc = []
    visited = [False] * (N + 1)
    while stack:
        node = stack.pop()
        if not visited[node]:
            scc.append([])
            dfs2(node, visited, graph, scc[-1])

    def dfs2(node, visited, graph, scc):
        visited[node] = True
        scc.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs2(neighbor, visited, graph, scc)

    if len(scc) == 1:
        print(scc[0][0])
    else:
        print(-1)

