    cookies = [list(input()) for _ in range(H)]

    while True:
        marked = [[False for _ in range(W)] for _ in range(H)]

        # Mark rows
        for i in range(H):
            if len(set(cookies[i])) == 1 and cookies[i][0]!= '.':
                for j in range(W):
                    marked[i][j] = True

        # Mark columns
        for j in range(W):
            column = [cookies[i][j] for i in range(H) if cookies[i][j]!= '.']
            if len(set(column)) == 1 and column:
                for i in range(H):
                    if cookies[i][j]!= '.':
                        marked[i][j] = True

        # Remove marked cookies
        removed = False
        for i in range(H):
            for j in range(W):
                if marked[i][j]:
                    cookies[i][j] = '.'
                    removed = True

        if not removed:
            break

    count = sum(1 for row in cookies for cookie in row if cookie!= '.')
    print(count)

