import itertools

def read_input():
    N = int(input())
    D = []
    for i in range(N-1):
        row = list(map(int, input().split()))
        D.append(row)
    return N, D

def compute_max_weight(N, D):
    max_weight = 0
    for r in range(N//2 + 1):
        for subset in itertools.combinations(range(N), 2*r):
            edges = []
            for i in range(r):
                edges.append((subset[2*i], subset[2*i+1]))
            valid = True
            for i in range(r):
                for j in range(i+1, r):
                    if edges[i][0] == edges[j][0] or edges[i][0] == edges[j][1] or edges[i][1] == edges[j][0] or edges[i][1] == edges[j][1]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                weight = 0
                for edge in edges:
                    weight += D[min(edge[0], edge[1])-1][max(edge[0], edge[1])-1-1]
                max_weight = max(max_weight, weight)
    return max_weight

N, D = read_input()
max_weight = compute_max_weight(N, D)
print(max_weight)

import sys
import itertools

def read_input():
    N = int(input())
    D = []
    for i in range(N-1):
        row = list(map(int, input().split()))
        D.append(row)
    return N, D

def compute_max_weight(N, D):
    max_weight = 0
    for r in range(1, N//2 + 1):
        for edges in itertools.combinations(range(N*(N-1)//2), r):
            edge_list = []
            for edge in edges:
                i = edge // (N-1)
                j = edge % (N-1)
                if j < i:
                    i, j = j, i
                edge_list.append((i, j))
            if is_valid(edge_list):
                weight = sum(D[i][j-i-1] for i, j in edge_list)
                max_weight = max(max_weight, weight)
    return max_weight

def is_valid(edge_list):
    vertices = set()
    for i, j in edge_list:
        if i in vertices or j in vertices:
            return False
        vertices.add(i)
        vertices.add(j)
    return True

def main():
    N, D = read_input()
    max_weight = compute_max_weight(N, D)
    print(max_weight)

if __name__ == "__main__":
