import itertools

# Read input
grid = [list(map(int, input().split())) for _ in range(3)]

# Function to check if a permutation is valid
def is_valid(permutation):
    # Check rows
    for i in range(3):
        row = [grid[i][j] for j in range(3)]
        for j in range(len(row) - 1):
            if row[permutation[i*3+j]] == row[permutation[i*3+j+1]] and row[permutation[i*3+j]] != row[permutation[i*3+j+2]]:
                return False

    # Check columns
    for i in range(3):
        col = [grid[j][i] for j in range(3)]
        for j in range(len(col) - 1):
            if col[permutation[j*3+i]] == col[permutation[j*3+i+3]] and col[permutation[j*3+i]] != col[permutation[j*3+i+6]]:
                return False

    # Check diagonals
    diagonal1 = [grid[i][i] for i in range(3)]
    for i in range(len(diagonal1) - 1):
        if diagonal1[permutation[i*3+i]] == diagonal1[permutation[i*3+i+4]] and diagonal1[permutation[i*3+i]] != diagonal1[permutation[i*3+i+8]]:
            return False

    diagonal2 = [grid[i][2-i] for i in range(3)]
    for i in range(len(diagonal2) - 1):
        if diagonal2[permutation[i*3+2-i]] == diagonal2[permutation[i*3+2-i+4]] and diagonal2[permutation[i*3+2-i]] != diagonal2[permutation[i*3+2-i+8]]:
            return False

    return True

# Generate all permutations
permutations = list(itertools.permutations(range(9)))

# Count valid permutations
valid_count = sum(1 for permutation in permutations if is_valid(permutation))

# Calculate probability
probability = valid_count / len(permutations)

# Print result
print(probability)

import sys

def check(width, n, m, lengths):
    lines = 1
    current_width = 0
    for length in lengths:
        if current_width + length + 1 > width:
            lines += 1
            current_width = 0
        if lines > m:
            return False
        current_width += length + 1
        if current_width > width:
            return False
    return True

n, m = map(int, input().split())
lengths = list(map(int, input().split()))

low = max(lengths)
high = sum(lengths) + n - 1

while low < high:
    mid = (low + high) // 2
    if check(mid, n, m, lengths):
