def find_min_time():
    min_time = float('inf')
    for digit in set(S[0]):
        if all(digit in s for s in S):
            times = []
            for s in S:
                for i, d in enumerate(s):
                    if d == digit:
                        times.append(i)
            for t in range(M * 10):
                if all((t - i) % M in times for i in range(len(S))):
                    min_time = min(min_time, max(t - i for i in range(len(S))))
    return min_time if min_time!= float('inf') else -1

