def read_input():
    lines = sys.stdin.readlines()
    N, M = map(int, lines[0].split())
    info = [list(map(int, line.split())) for line in lines[1:]]
    return N, M, info

def solve(N, M, info):
    coordinates = {1: (0, 0)}
    for A, B, X, Y in info:
        if A not in coordinates:
            continue
        if B in coordinates:
            continue
        Ax, Ay = coordinates[A]
        coordinates[B] = (Ax + X, Ay + Y)
    for i in range(1, N + 1):
        if i not in coordinates:
            print("undecidable")
        else:
            print(*coordinates[i])

