import sys

def read_input():
    lines = sys.stdin.readlines()
    N, M = map(int, lines[0].split())
    edges = []
    for line in lines[1:]:
        A, B, X, Y = map(int, line.split())
        edges.append((A, B, X, Y))
    return N, M, edges

def compute_coordinates(N, M, edges):
    coordinates = {1: (0, 0)}
    for A, B, X, Y in edges:
        if A not in coordinates:
            continue
        Ax, Ay = coordinates[A]
        if B in coordinates:
            Bx, By = coordinates[B]
            if Bx != Ax + X or By != Ay + Y:
                return ["undecidable"] * N
        else:
            coordinates[B] = (Ax + X, Ay + Y)
    for A, B, X, Y in edges:
        if B not in coordinates:
            Ax, Ay = coordinates[A]
            coordinates[B] = (Ax + X, Ay + Y)
    result = []
    for i in range(1, N + 1):
        if i in coordinates:
            x, y = coordinates[i]
            result.append(f"{x} {y}")
        else:
            result.append("undecidable")
    return result

def main():
    N, M, edges = read_input()
    result = compute_coordinates(N, M, edges)
    for line in result:
        print(line)

if __name__ == "__main__":
    main()

