import itertools

def generate_321_like_numbers():
    """Generate 321-like numbers."""
    digits = '9876543210'
    for r in range(1, 11):
        for combination in itertools.combinations(digits, r):
            yield int(''.join(combination))

def find_kth_smallest(k):
    """Find the k-th smallest 321-like number."""
    numbers = generate_321_like_numbers()
    for _ in range(k - 1):
        next(numbers)
    return next(numbers)

