def fits(grid, polyomino, x, y):
    for i in range(4):
        for j in range(4):
            if polyomino[i][j] == '#':
                if x + i < 0 or x + i >= 4 or y + j < 0 or y + j >= 4:
                    return False
                if grid[x + i][y + j] == '#':
                    return False
    return True

