import sys
import itertools

def rotate(polyomino):
    return [''.join(reversed(i)) for i in zip(*polyomino)]

def get_polyominoes():
    polyominoes = []
    for _ in range(3):
        polyomino = [input() for _ in range(4)]
        polyominoes.append(polyomino)
    return polyominoes

def get_all_orientations(polyomino):
    orientations = [polyomino]
    for _ in range(3):
        polyomino = rotate(polyomino)
        orientations.append(polyomino)
    return orientations

def get_all_positions(polyomino):
    positions = []
    for i in range(4 - len(polyomino) + 1):
        for j in range(4 - len(polyomino[0]) + 1):
            position = [[0]*4 for _ in range(4)]
            for k, row in enumerate(polyomino):
                for col, cell in enumerate(row):
                    if cell == '#':
                        position[i+k][j+col] = 1
            positions.append(position)
    return positions

def is_valid_position(position):
    for row in position:
        for cell in row:
            if cell > 1:
                return False
    return True

def is_full(position):
    for row in position:
        for cell in row:
            if cell == 0:
                return False
    return True

def main():
    polyominoes = get_polyominoes()
    all_orientations = [get_all_orientations(polyomino) for polyomino in polyominoes]
    all_positions = [[get_all_positions(orientation) for orientation in orientations] for orientations in all_orientations]

    for positions in itertools.product(*[position for positions in all_positions for position in positions]):
        combined_position = [[0]*4 for _ in range(4)]
        for position in positions:
            for i in range(4):
                for j in range(4):
                    combined_position[i][j] += position[i][j]
        if is_valid_position(combined_position) and is_full(combined_position):
            print('Yes')
            return
    print('No')

if __name__ == '__main__':
    main()

