import sys

def calculate_score(A, S, i):
    score = i
    for j in range(len(S)):
        if S[j] == 'o':
            score += A[j]
    return score

def main():
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    S = [input() for _ in range(N)]

    for i in range(N):
        current_score = calculate_score(A, S[i], i + 1)
        max_other_score = max(calculate_score(A, S[j], j + 1) for j in range(N) if j != i)
        problems_solved = 0
        remaining_score = current_score
        sorted_problems = sorted((A[j], j) for j in range(M) if S[i][j] == 'x')
        for score, j in sorted_problems:
            remaining_score += score
            problems_solved += 1
            if remaining_score > max_other_score:
                break
        print(problems_solved)

