import sys

def calculate_total_score(A, S, i):
    """Calculate the total score of a player."""
    total_score = 0
    for j in range(len(S)):
        if S[j] == 'o':
            total_score += A[j]
    total_score += i + 1
    return total_score

def find_problems_to_solve(A, S, i, other_scores):
    """Find the number of problems a player needs to solve to exceed all other players' scores."""
    player_score = calculate_total_score(A, S[i], i + 1)
    problems_to_solve = 0
    while True:
        if all(player_score > score for score in other_scores):
            break
        max_problem_score = 0
        max_problem_index = -1
        for j in range(len(S[i])):
            if S[i][j] == 'x' and A[j] > max_problem_score:
                max_problem_score = A[j]
                max_problem_index = j
        if max_problem_index == -1:
            break
        S[i] = S[i][:max_problem_index] + 'o' + S[i][max_problem_index + 1:]
        player_score += max_problem_score
        problems_to_solve += 1
    return problems_to_solve

def main():
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    S = [input() for _ in range(N)]

    for i in range(N):
        other_scores = [calculate_total_score(A, S[j], j + 1) for j in range(N) if j != i]
        problems_to_solve = find_problems_to_solve(A, S, i, other_scores)
        print(problems_to_solve)

if __name__ == "__main__":
    main()

import sys

def is_equal(s1, s2):
    return s1 == s2

def is_inserted(s1, s2):
    if len(s1)!= len(s2) + 1:
        return False
    i, j = 0, 0
    while i < len(s1) and j < len(s2):
        if s1[i]!= s2[j]:
            if i > 0 and s1[i-1] == s2[j]:
                i += 1
            else:
                return False
        else:
            i += 1
            j += 1
    return True

def is_deleted(s1, s2):
    if len(s1)!= len(s2) - 1:
        return False
    i, j = 0, 0
    while i < len(s1) and j < len(s2):
        if s1[i]!= s2[j]:
            if i > 0 and s1[i] == s2[j-1]:
                j += 1
            else:
                return False
        else:
            i += 1
            j += 1
    return True

def is_replaced(s1, s2):
    if len(s1)!= len(s2):
        return False
    diff = 0
    for i in range(len(s1)):
        if s1[i]!= s2[i]:
            diff += 1
        if diff > 1:
            return False
    return diff == 1

