import sys
from collections import defaultdict

def dfs(graph, node, parent):
    """Perform DFS traversal from the given node."""
    count = 0
    for child in graph[node]:
        if child != parent:
            count += dfs(graph, child, node)
    return max(count, 1)

def main():
    """Read input, compute answer, and print result."""
    n = int(input())
    graph = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    result = dfs(graph, 1, -1)
    print(result)

