def is_semi_palindrome(s):
    n = len(s)
    for d in range(1, n):
        if n % d == 0:
            for i in range(d):
                if s[i] != s[n - i - 1]:
                    break
            else:
                return True
    return False

def min_changes(s):
    n = len(s)
    changes = 0
    for i in range(0, n, 2):
        substring = s[i:i + 2]
        if not is_semi_palindrome(substring):
            changes += 1
    return changes

def min_changes_k(s, k):
    n = len(s)
    min_changes = float('inf')
    for i in range(1 << (n - 1)):
        substrings = []
        start = 0
        count = 0
        for j in range(n - 1):
            if (i & (1 << j)) != 0:
                substrings.append(s[start:j + 1])
                start = j + 1
                count += 1
        substrings.append(s[start:])
        if count == k - 1:
            changes = 0
            for substring in substrings:
                if not is_semi_palindrome(substring):
                    changes += min_changes_to_palindrome(substring)
            min_changes = min(min_changes, changes)
    return min_changes

def min_changes_to_palindrome(s):
    n = len(s)
    changes = 0
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            changes += 1
    return changes

