    return False

def min_changes(s):
    n = len(s)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            substring = s[i:j + 1]
            changes = 0
            for d in range(1, length):
                if length % d == 0:
                    for k in range(d):
                        count = {}
                        for index in range(k, length, d):
                            count[substring[index]] = count.get(substring[index], 0) + 1
                        changes = max(changes, len(count) - max(count.values()))
            dp[i][j + 1] = changes
    return dp

def min_k_changes(s, k):
    n = len(s)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    changes = min_changes(s)
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for m in range(j - 1, i):
                dp[i][j] = min(dp[i][j], dp[m][j - 1] + changes[m][i])
    return dp[n][k]

