import sys

def is_semi_palindrome(s):
    n = len(s)
    for d in range(1, n):
        if n % d == 0:
            for i in range(d):
                if s[i] != s[n - i - 1]:
                    break
            else:
                return True
    return False

def min_changes_to_semi_palindrome(s):
    n = len(s)
    k = int(input().split()[1])
    memo = {}

    def dp(i, k):
        if (i, k) in memo:
            return memo[(i, k)]
        if k == 1:
            changes = 0
            for d in range(1, n - i + 1):
                if (n - i) % d == 0:
                    for j in range(d):
                        changes += sum(s[i + j + x * d] != s[i + d - j - 1 - x * d] for x in range((n - i - d) // d + 1))
                    break
            else:
                changes = float('inf')
            memo[(i, k)] = changes
            return changes
        res = float('inf')
        for j in range(1, n - i - k + 2):
            changes = 0
            for d in range(1, j):
                if j % d == 0:
                    for x in range(d):
                        changes += sum(s[i + x + y * d] != s[i + d - x - 1 - y * d] for y in range((j - d) // d + 1))
                    break
            else:
                changes = float('inf')
            res = min(res, changes + dp(i + j, k - 1))
        memo[(i, k)] = res
        return res

    print(dp(0, k))

