import sys

MOD = 10**9 + 7

def read_input():
    s = input()
    t = input()
    k = int(input())
    return s, t, k

def count_ways(s, t, k):
    n = len(s)
    count = 0
    for i in range(n):
        new_s = s[i:] + s[:i]
        if new_s == t:
            count += 1
    if k == 1:
        return count % MOD
    else:
        # Calculate the number of ways to transform s into t in k operations
        # using the fact that the transformation is cyclic
        ways = 0
        for i in range(n):
            if s[i:] + s[:i] == t:
                ways += 1
        ways %= MOD
        # Calculate the number of ways to transform s into t in k-1 operations
        # and then apply one more operation
        ways_k_1 = count_ways(s, t, k-1)
        return (ways_k_1 * ways) % MOD

def main():
    s, t, k = read_input()
    print(count_ways(s, t, k))

if __name__ == "__main__":
    main()

