import heapq

def main():
    nums = list(map(int, input().split()))
    target = int(input())

    pq = []
    for num in nums:
        heapq.heappush(pq, -num)

    operations = 0
    while pq:
        num = -heapq.heappop(pq)
        if num <= target:
            target -= num
            if target == 0:
                break
        else:
            heapq.heappush(pq, -num // 2)
            heapq.heappush(pq, -num // 2)
            operations += 1

    if target != 0:
        print(-1)
    else:
        print(operations)

if __name__ == "__main__":
    main()

