    target = int(input())

    pq = []
    for num in nums:
        heapq.heappush(pq, -num)

    operations = 0
    while pq:
        num = -heapq.heappop(pq)
        if num == target:
            break
        elif num > target:
            heapq.heappush(pq, -num // 2)
            heapq.heappush(pq, -num // 2)
            operations += 1
        else:
            heapq.heappush(pq, -num)
            if not pq:
                break

    if pq and -max(pq) == target:
