def is_perfect_square(n):
    root = math.isqrt(n)
    return root * root == n

def main():
    nums = list(map(int, input().split()))
    n = len(nums)
    max_sum = 0

    for mask in range(1, 1 << n):
        subset_sum = 0
        is_complete = True

        for i in range(n):
            if (mask & (1 << i)) != 0:
                subset_sum += nums[i]
                for j in range(i + 1, n):
                    if (mask & (1 << j)) != 0 and not is_perfect_square(nums[i] * nums[j]):
                        is_complete = False
                        break
                if not is_complete:
                    break

        if is_complete:
            max_sum = max(max_sum, subset_sum)

    print(max_sum)

