import sys
from collections import Counter

MOD = 10**9 + 7

def count_sub_multisets(nums, l, r):
    count = Counter(nums)
    dp = [0] * (r + 1)
    dp[0] = 1

    for num, freq in count.items():
        for i in range(r, num - 1, -1):
            for j in range(1, freq + 1):
                if i - j * num >= 0:
                    dp[i] = (dp[i] + dp[i - j * num]) % MOD

    return sum(dp[l:r+1]) % MOD

