    max_score = 0
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += nums[j] - nums[i]
        if total <= k:
            max_score = max(max_score, j - i + 1)
        else:
            break
    for i in range(n - 1, -1, -1):
        total = 0
        for j in range(i, -1, -1):
            total += nums[i] - nums[j]
        if total <= k:
            max_score = max(max_score, i - j + 1)
        else:
            break
    print(max_score)

