def main():
    nums = list(map(int, input().split()))
    k = int(input())
    nums.sort()
    n = len(nums)
    max_score = 0

    for i in range(n):
        total = 0
        for j in range(i, n):
            total += nums[j] - nums[i]
        if total <= k:
            max_score = max(max_score, j - i + 1)

        left = i - 1
        for j in range(i, n):
            total += nums[j] - nums[i]
            while total > k and left >= 0:
                total -= nums[i] - nums[left]
                left -= 1
            if total <= k:
                max_score = max(max_score, j - left)

    print(max_score)

