import sys
from collections import Counter

def main():
    s = input()
    queries = []
    for line in sys.stdin:
        queries.append(list(map(int, line.split())))

    n = len(s)
    answer = []
    for query in queries:
        a, b, c, d = query
        left = s[a:b+1]
        right = s[c:d+1]
        left_count = Counter(left)
        right_count = Counter(right)
        mid = s[b+1:c]
        mid_count = Counter(mid)

        possible = True
        for char in left_count:
            if left_count[char] - right_count.get(char, 0) > 1:
                possible = False
                break
            if left_count[char] - right_count.get(char, 0) == 1:
                if mid_count.get(char, 0) == 0:
                    possible = False
                    break
                mid_count[char] -= 1
        if possible:
            for char in right_count:
                if right_count[char] - left_count.get(char, 0) > 1:
                    possible = False
                    break
                if right_count[char] - left_count.get(char, 0) == 1:
                    if mid_count.get(char, 0) == 0:
                        possible = False
                        break
                    mid_count[char] -= 1
        answer.append(possible)

    print(answer)

