import sys

def count_chars(s):
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

def can_make_palindrome(s, queries):
    n = len(s)
    mid = n // 2
    answer = []

    for query in queries:
        a, b, c, d = query
        left_substring = s[a:b+1]
        right_substring = s[c:d+1]

        left_char_count = count_chars(left_substring)
        right_char_count = count_chars(right_substring)

        left_remaining = {}
        right_remaining = {}

        for char in left_char_count:
            if char in right_char_count:
                min_count = min(left_char_count[char], right_char_count[char])
                left_remaining[char] = left_char_count[char] - min_count
                right_remaining[char] = right_char_count[char] - min_count
            else:
                left_remaining[char] = left_char_count[char]

        for char in right_char_count:
            if char not in left_char_count:
                right_remaining[char] = right_char_count[char]

        odd_count = 0
        for char in left_remaining:
            odd_count += left_remaining[char] % 2
        for char in right_remaining:
            odd_count += right_remaining[char] % 2

        middle_substring = s[b+1:c]
        middle_char_count = count_chars(middle_substring)
        for char in middle_char_count:
            odd_count += middle_char_count[char] % 2

        if odd_count <= 1:
            answer.append(True)
        else:
            answer.append(False)

    return answer

s = input().strip('"')
queries = []
for line in sys.stdin:
    queries.append(list(map(int, line.strip().split())))

answer = can_make_palindrome(s, queries)
print(answer)

import sys

def find_max_length(nums):
    n = len(nums)
    max_length = 1
    for i in range(n):
        for j in range(i, n):
            new_nums = []
            total = 0
            for k in range(n):
                if k < i or k > j:
                    new_nums.append(nums[k])
                else:
                    total += nums[k]
            if i == 0 and j == n - 1:
                new_nums.append(total)
            elif i == 0:
                new_nums.append(total)
                new_nums.extend(nums[j + 1:])
            elif j == n - 1:
                new_nums.extend(nums[:i])
                new_nums.append(total)
            else:
                new_nums.extend(nums[:i])
                new_nums.append(total)
                new_nums.extend(nums[j + 1:])
            is_non_decreasing = all(new_nums[k] <= new_nums[k + 1] for k in range(len(new_nums) - 1))
            if is_non_decreasing:
                max_length = max(max_length, len(new_nums))
    return max_length

nums = list(map(int, input().split()))
print(find_max_length(nums))

