def is_non_decreasing(arr):
    return all(arr[i] <= arr[i+1] for i in range(len(arr)-1))

def find_max_length(nums):
    n = len(nums)
    max_length = 1
    for i in range(n):
        for j in range(i, n):
            subarray = nums[i:j+1]
            subarray_sum = sum(subarray)
            new_array = nums[:i] + [subarray_sum] + nums[j+1:]
            if is_non_decreasing(new_array):
                max_length = max(max_length, len(new_array))
    return max_length

