import sys

def count_partitions(s, k):
    count = 0
    while s:
        prefix = ''
        distinct_chars = set()
        for char in s:
            if char not in distinct_chars and len(distinct_chars) < k:
                prefix += char
                distinct_chars.add(char)
            elif char in distinct_chars:
                prefix += char
            else:
                break
        s = s[len(prefix):]
        count += 1
    return count

