import sys

def calculate_or(nums):
    result = 0
    for num in nums:
        result |= num
    return result

def main():
    nums = list(map(int, input().split()))
    k = int(input())
    n = len(nums)
    min_or = float('inf')
    for mask in range(1 << n):
        if bin(mask).count('1') <= k:
            new_nums = []
            i = 0
            while i < n:
                if (mask & (1 << i)) == 0:
                    new_nums.append(nums[i])
                    i += 1
                else:
                    j = i
                    while j < n and (mask & (1 << j))!= 0:
                        j += 1
                    and_result = nums[i]
                    for p in range(i + 1, j):
                        and_result &= nums[p]
                    new_nums.append(and_result)
                    i = j
            min_or = min(min_or, calculate_or(new_nums))
    print(min_or)

if __name__ == "__main__":
    main()

