import sys
from collections import deque

def main():
    H, W, T = map(int, input().split())
    grid = [list(input()) for _ in range(H)]

    start = None
    goal = None
    candies = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def bfs(start, goal, max_moves, candies):
        queue = deque([(start, 0, 0)])
        visited = set([start])
        max_candies = 0

        while queue:
            (x, y), moves, candies_collected = queue.popleft()

            if (x, y) == goal and moves <= max_moves:
                max_candies = max(max_candies, candies_collected)

            if moves >= max_moves:
                continue

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if (0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and (nx, ny) not in visited):
                    new_candies_collected = candies_collected + (1 if (nx, ny) in candies else 0)
                    queue.append(((nx, ny), moves + 1, new_candies_collected))
                    visited.add((nx, ny))

        return max_candies

    max_candies = bfs(start, goal, T, candies)

    if max_candies == 0 and start != goal:
        print(-1)
    else:
        print(max_candies)

if __name__ == "__main__":
    main()

from collections import deque
import sys

def read_input():
    H, W, T = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]
    return H, W, T, grid

def find_start(grid):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'S':
                return i, j

def find_goal(grid):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'G':
                return i, j

def find_candies(grid):
    candies = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'o':
                candies.append((i, j))
    return candies

def bfs(grid, start, goal, candies, T):
    queue = deque([(start, 0, 0)])
    visited = set([start])
    max_candies = 0
    while queue:
        (x, y), moves, candy_count = queue.popleft()
        if (x, y) == goal:
            max_candies = max(max_candies, candy_count)
        if moves >= T:
            continue
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if (0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and
                    grid[nx][ny] != '#' and (nx, ny) not in visited):
                new_candy_count = candy_count + (grid[nx][ny] == 'o')
                queue.append(((nx, ny), moves + 1, new_candy_count))
                visited.add((nx, ny))
    return max_candies

def main():
    H, W, T, grid = read_input()
    start = find_start(grid)
    goal = find_goal(grid)
    candies = find_candies(grid)
    max_candies = bfs(grid, start, goal, candies, T)
    if max_candies == 0 and start != goal:
        print(-1)
    else:
        print(max_candies)

if __name__ == '__main__':
    main()

