MOD = 998244353

def count_no_ddos(s):
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        if s[i - 1] == '?':
            dp[i] = (2 * dp[i - 1]) % MOD
        elif s[i - 1].isupper():
            dp[i] = dp[i - 1]
        else:
