    """Read input, compute the answer, and print the result."""
    n = int(input())
    a = list(map(int, input().split()))
    s = input()

    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if s[i] + s[j] + s[k] == 'MEX':
                    total += mex(a[i], a[j], a[k])

    print(total)

