import sys
from itertools import product

MOD = 998244353

def mod_inverse(a, m):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return gcd, y - (b // a) * x, x

    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        return None
    else:
        return x % m

def main():
    N = int(input())
    A = list(map(int, input().split()))

    total_outcomes = 1
    for a in A:
        total_outcomes = (total_outcomes * a) % MOD

    successful_outcomes = 0
    for p in product(*[range(a + 1) for a in A]):
        for mask in range(1 << N):
            subset_sum = sum([p[i] for i in range(N) if (mask & (1 << i))])
            if subset_sum == 10:
                successful_outcomes += 1
                break

    successful_outcomes %= MOD
    probability = (successful_outcomes * mod_inverse(total_outcomes, MOD)) % MOD
    print(probability)

if __name__ == "__main__":
    main()

