                x1, y1, z1, x2, y2, z2 = cuboids[i]
                x3, y3, z3, x4, y4, z4 = cuboids[j]
                if (x1 == x3 and x2 == x4) or (x1 == x4 and x2 == x3):
                    if (y1 == y3 and y2 == y4) or (y1 == y4 and y2 == y3):
                        if z1 == z2 and z3 == z4 and (z1 == z3 or z1 == z4 or z2 == z3 or z2 == z4):
                            counts[i] += 1
                    elif (z1 == z3 and z2 == z4) or (z1 == z4 and z2 == z3):
                        if y1 == y2 and y3 == y4 and (y1 == y3 or y1 == y4 or y2 == y3 or y2 == y4):
                            counts[i] += 1
                elif (y1 == y3 and y2 == y4) or (y1 == y4 and y2 == y3):
                    if (z1 == z3 and z2 == z4) or (z1 == z4 and z2 == z3):
                        if x1 == x2 and x3 == x4 and (x1 == x3 or x1 == x4 or x2 == x3 or x2 == x4):
                            counts[i] += 1
                    elif (x1 == x3 and x2 == x4) or (x1 == x4 and x2 == x3):
