import sys

def main():
    N, M = map(int, input().split())
    items = []
    for _ in range(N):
        T, X = map(int, input().split())
        items.append((T, X))

    items.sort(key=lambda x: x[1], reverse=True)

    pull_tab_cans = []
    regular_cans = []
    can_openers = []
    for item in items:
        if item[0] == 0:
            pull_tab_cans.append(item[1])
        elif item[0] == 1:
            regular_cans.append(item[1])
        else:
            can_openers.append(item[1])

    max_happiness = 0
    for i in range(min(M, len(pull_tab_cans)) + 1):
        for j in range(min(M - i, len(regular_cans)) + 1):
            k = M - i - j
            if k > len(can_openers):
                continue
            if k > 0:
                opener_capacity = sum(sorted(can_openers, reverse=True)[:k])
                if opener_capacity < j:
                    continue
            happiness = sum(sorted(pull_tab_cans, reverse=True)[:i]) + sum(sorted(regular_cans, reverse=True)[:j])
            max_happiness = max(max_happiness, happiness)

    print(max_happiness)

