import sys

MOD = 998244353

def mod_inverse(a, m):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return gcd, y - (b // a) * x, x

    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        return None
    else:
        return x % m

def main():
    N = int(input())
    p = []
    q = []
    for _ in range(N - 1):
        p_i, q_i = map(int, input().split())
        p.append(p_i)
        q.append(q_i)

    E = [1] * N
    for i in range(N - 1):
        p_i = p[i] - 1
        q_i = q[i] - 1
        a = sum(1 for j in range(N) if E[j] == 1 and j != q_i)
        b = N - a
        prob = a * mod_inverse(a + b, MOD)
        for j in range(N):
            if E[j] == 1 and j != q_i:
                E[j] = prob
        E[q_i] = 1 - prob

    print(' '.join(str(int(E_i * MOD)) for E_i in E))

if __name__ == '__main__':
    main()

from collections import defaultdict, deque

def main():
    N = int(input())
    graph = defaultdict(list)
    indegree = [0] * (N + 1)

    for i in range(1, N + 1):
        C, *P = map(int, input().split())
        for p in P:
            graph[p].append(i)
            indegree[i] += 1

    queue = deque([i for i in range(1, N + 1) if indegree[i] == 0])
    result = []

    while queue:
        node = queue.popleft()
        if node != 1:
            result.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    print(*result[::-1])

if __name__ == "__main__":
    main()

import sys
import math

def calculate_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def main():
    N = int(input())
    checkpoints = []
    for _ in range(N):
        x, y = map(int, input().split())
        checkpoints.append((x, y))

    min_distance = float('inf')
    for mask in range(1 << (N - 2)):
        current_distance = 0
        previous_checkpoint = checkpoints[0]
        skipped_checkpoints = 0
        for i in range(1, N - 1):
            if (mask & (1 << (i - 1))) == 0:
                current_distance += calculate_distance(previous_checkpoint[0], previous_checkpoint[1], checkpoints[i][0], checkpoints[i][1])
                previous_checkpoint = checkpoints[i]
                skipped_checkpoints += 1
            else:
                skipped_checkpoints += 1
        current_distance += calculate_distance(previous_checkpoint[0], previous_checkpoint[1], checkpoints[-1][0], checkpoints[-1][1])
        if skipped_checkpoints > 0:
            current_distance += 2 ** (skipped_checkpoints - 1)
        min_distance = min(min_distance, current_distance)

    print(min_distance)

if __name__ == "__main__":
    main()
